-- generated by desktop-set (Settings > Interface > Dock, Settings > Desktop > Widgets)
hl.layer_rule({
    name  = "rice-dock-blur",
    match = { namespace = "rice-dock" },
    blur = true,
    ignore_alpha = 0.1,
})
hl.layer_rule({
    name  = "rice-widget-blur",
    match = { namespace = "rice-widget" },
    blur = true,
    ignore_alpha = 0.2,
})
